Run ID: replay-ledger-1
Objective: Fix src/ledger/ledger.js so applyPayment rejects Infinity amounts (returns false) and keeps finite amounts.
Existing:
--- src/ledger/ledger.js ---
export function applyPayment(amount) {
  if (amount == null) return false;
  return true;
}
Return worker plan JSON updating ledger.js with complete contents and a node:test file.

message.content:
{
  "runId": "replay-ledger-1",
  "summary": "Fix src/ledger/ledger.js to reject Infinity amounts and keep finite amounts, and add a test file to verify the behavior.",
  "allowedFiles": [
    "src/ledger/ledger.js",
    "test/ledger.test.js"
  ],
  "operations": [
    {
      "type": "update_file",
      "path": "src/ledger/ledger.js",
      "content": "export function applyPayment(amount) {\n  if (amount == null) return false;\n  return Number.isFinite(amount);\n}",
      "reason": "Reject Infinity amounts by returning false when amount is not finite, while keeping true for finite amounts."
    },
    {
      "type": "create_file",
      "path": "test/ledger.test.js",
      "content": "import { applyPayment } from '../src/ledger/ledger.js';\nimport assert from 'node:assert/strict';\n\n// Test that finite numbers return true\nassert.strictEqual(applyPayment(100), true, 'Finite positive amount should be accepted');\nassert.strictEqual(applyPayment(-50), true, 'Finite negative amount should be accepted');\nassert.strictEqual(applyPayment(0), true, 'Zero should be accepted');\nassert.strictEqual(applyPayment(3.14), true, 'Positive float should be accepted');\n\n// Test that Infinity and NaN return false\nassert.strictEqual(applyPayment(Infinity), false, 'Infinity should be rejected');\nassert.strictEqual(applyPayment(-Infinity), false, '-Infinity should be rejected');\nassert.strictEqual(applyPayment(NaN), false, 'NaN should be rejected');\nassert.strictEqual(applyPayment(null), false, 'null should be rejected');\nassert.strictEqual(applyPayment(undefined), false, 'undefined should be rejected');\n\nconsole.log('All tests passed');\n",
      "reason": "Add a comprehensive test file using only node:test and node:assert/strict to verify the corrected behavior of applyPayment."
    }
  ]
}
